package net.officefloor.hq.app.grade;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** How many people the merge gave the other grade. */
public class RespondWithGradeMerged {
    public void respond(@Val GradeMerged merged, ObjectResponse<GradeMerged> response) {
        response.send(merged);
    }
}
EOF
cat > "resources/officefloor/rest/api/sheets/{sheetId}/grades/merge.POST.yml" <<'EOF'
# Merge a grade into another (GRADE_MERGED): every person whose grade in force on the sheet's today is the merged one
# is given the other from that today, each as the person form saves it (PERSON_EDITED and its rollup lines), in list
# order. Anyone but a steward, the same grade twice, a grade other than A, B, C, or a retired grade to merge into is
# refused (400). Responds with how many people were given the other grade.
archived:
  class: net.officefloor.hq.app.sheet.CheckNotArchived
  next: viewer
viewer:
  class: net.officefloor.hq.app.setting.CheckNotViewer
  next: steward
steward:
  class: net.officefloor.hq.app.grade.CheckGradeMergeSteward
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: validate
validate:
  class: net.officefloor.hq.app.grade.ValidateGradeMergeRequest
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.grade.AuditGradeMerged
  govern: [ transaction ]
  next: merge
merge:
  class: net.officefloor.hq.app.grade.MergeGrade
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.grade.RespondWithGradeMerged
  govern: [ transaction ]
EOF
