 * boundary date (its due-by plus the grace days of its person's grade on its date plus 30, 60, 90 ... days) of the figure
 * plus the charges of the boundaries before it, rounded like the claim's due, the charges added up (a boundary at 0.00
 * adds nothing); 0.00 when it is not overdue, and always for a correction or a claim whose charge was waived.
 */
export function lateCharge(claim: Claim, figure: string, grades: GradeFrom[], rules: DueRules): string {
  if (claim.corrects !== null || claim.waived) return '0.00';
  const grace = claimGrace(claim, grades, rules);
  const periods = latePeriods(claim, rules.today, grace);
  const charges: string[] = [];
  for (let period = 1; period <= periods; period++) {
    const pct = hundredths(rules.latePctOn(lateBoundary(claim, period, grace)));
    if (pct !== 0) charges.push(percentOf(hundredths(total([figure, ...charges])), pct, roundingFor(claim, rules)));
  }
  return total(charges);
}

/**
 * A claim's due: the one fixed when it was settled (any late charge and floor frozen in), else the due its
 * statement bound it to (late charge and floor included, as shown when it was taken), else the greater of the floor in
 * force on its date and its figure, plus the late charge on that floored figure while it is overdue — a correction has no floor and no
 * charge.
 */
export function claimDue(claim: Claim, rates: Rate[], grades: GradeFrom[], rules: DueRules): string {
  if (claim.due !== null) return claim.due;
  const figure = claimFigure(claim, rates, grades, rules);
  if (figure === NA || bound(claim) || claim.corrects !== null) return figure;
  const raised = floored(figure, rules.floorOn(claim.date));
  return total([raised, lateCharge(claim, raised, grades, rules)]);
}

/** Whether a claim keeps a figure whatever the rates: fixed when settled, or bound by a statement. */
const keepsFigure = (c: Claim) => c.due !== null || (bound(c) && c.statedDue !== null);

/**
 * A person's due-total: the figures of their claims that count, added up (0.00 with none). With no
 * rate in force on the sheet's today for their grade on that day it is n/a, unless a claim has a figure (kept
 * when settled or stated, or at the rate for the grade in force on its date): then it is the figures there are,
 * added up. Their open claims a hold covers (not bound by a statement) do not count. With `shared`, shared claims are
 * parted between their own person and their holders. The sheet's cap covers it plus their cut total: it is at most
 * the cap less their cut total, not below 0.00 (n/a is not capped).
 */
export function personDue(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  holds: Hold[],
  rules: DueRules,
  shared?: Shared,
): string {
  const sum = personSum(claims, rates, grades, holds, rules, shared);
  if (sum === NA || rules.cap === '') return sum;
  const room = Math.max(0, hundredths(rules.cap) - personCut(rules, shared));
  return hundredths(sum) <= room ? sum : (room / 100).toFixed(2);
}

/** A person's cut total in whole hundredths (0 when not told who they are). */
const personCut = (rules: DueRules, shared?: Shared) => (shared ? hundredths(rules.cutOf(shared.personId)) : 0);

/**
 * A person's excess: by how much their due-total plus their cut total is above the sheet's cap; 0.00 when it is
 * not (or the due-total is n/a).
 */
export function personExcess(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  holds: Hold[],
  rules: DueRules,
  shared?: Shared,
): string {
  const sum = personSum(claims, rates, grades, holds, rules, shared);
  if (sum === NA || rules.cap === '') return '0.00';
  return (Math.max(0, hundredths(sum) + personCut(rules, shared) - hundredths(rules.cap)) / 100).toFixed(2);
}

